#!/usr/bin/env python3
"""v0.8.3: one intentional, ergonomic model picker pill."""
from pathlib import Path
import re
import xml.etree.ElementTree as ET

root=Path(__file__).resolve().parents[1]
layout=root/"app/src/main/res/layout/activity_main.xml"
colors=root/"app/src/main/res/values/colors.xml"
gradle=root/"app/build.gradle.kts"
src=layout.read_text()

# Only replace the model control generated by v0.8.2. No model or inference code changes.
start=src.find('<com.google.android.material.card.MaterialCardView\n',src.find('android:id="@+id/composerCard"'))
if start<0 or 'android:id="@+id/modelCard"' not in src[start:start+240]:
    raise SystemExit("cannot identify v0.8.2 model selector")
end_tag='</com.google.android.material.card.MaterialCardView>'
end=src.find(end_tag,start)
if end<0:
    raise SystemExit("cannot locate model selector end")
end+=len(end_tag)

replacement='''<com.google.android.material.card.MaterialCardView
                        android:id="@+id/modelCard"
                        android:layout_width="wrap_content"
                        android:layout_height="40dp"
                        android:layout_gravity="center_vertical"
                        android:clickable="true"
                        android:focusable="true"
                        android:contentDescription="Choose a local model"
                        android:foreground="?attr/selectableItemBackground"
                        app:cardBackgroundColor="@color/model_picker_background"
                        app:cardCornerRadius="20dp"
                        app:cardElevation="0dp"
                        app:strokeWidth="0dp">

                        <LinearLayout
                            android:layout_width="wrap_content"
                            android:layout_height="match_parent"
                            android:gravity="center_vertical"
                            android:orientation="horizontal"
                            android:paddingStart="14dp"
                            android:paddingEnd="11dp">

                            <TextView
                                android:id="@+id/modelNameView"
                                android:layout_width="wrap_content"
                                android:layout_height="wrap_content"
                                android:ellipsize="end"
                                android:maxLines="1"
                                android:maxWidth="162dp"
                                android:text="Choose model"
                                android:textColor="@color/text_primary"
                                android:textSize="14sp"
                                android:fontFamily="sans-serif-medium" />

                            <ImageView
                                android:layout_width="18dp"
                                android:layout_height="18dp"
                                android:layout_marginStart="8dp"
                                android:contentDescription="Open model list"
                                android:src="@drawable/ic_model_chevron" />

                            <TextView
                                android:id="@+id/contextView"
                                android:layout_width="wrap_content"
                                android:layout_height="wrap_content"
                                android:visibility="gone" />
                        </LinearLayout>
                    </com.google.android.material.card.MaterialCardView>'''
src=src[:start]+replacement+src[end:]
ET.fromstring(src)
layout.write_text(src)

pal=colors.read_text()
if '<color name="model_picker_background">' not in pal:
    pal=pal.replace('</resources>','    <color name="model_picker_background">#414141</color>\n</resources>')
colors.write_text(pal)
build=gradle.read_text()
build=re.sub(r'versionCode = \d+', 'versionCode = 103', build,count=1)
build=re.sub(r'versionName = "[^"]+"', 'versionName = "0.8.3-oled-experimental"',build,count=1)
gradle.write_text(build)

assert src.count('android:id="@+id/modelCard"')==1
assert src.count('android:id="@+id/modelNameView"')==1
assert src.count('android:id="@+id/contextView"')==1
assert 'android:src="@drawable/ic_model_chevron"' in src
assert 'app:cardCornerRadius="20dp"' in src
assert src.index('android:id="@+id/modelCard"')>src.index('android:id="@+id/composerCard"')
assert 'model_picker_background' in pal
print("v0.8.3 model selector: accessible compact pill, padded label, real vector chevron")
